 async function confirm(){if(!confirmation||busy)return;let ok=false;const requestId=confirmation.requestId;if(confirmation.kind==='order'){ok=await mutate('order',{requestId,order:confirmation.order},'Orden simulada registrada.');if(ok)setOrder(previous=>({...previous,quantity:'',note:''}));}else if(confirmation.kind==='cash'){ok=await mutate('cash',{requestId,kind:confirmation.cashKind,amount:confirmation.amount},'Movimiento de capital registrado.');if(ok)setCashAmount('');}else if(confirmation.kind==='settings')ok=await mutate('settings',{requestId,feePerOrder:confirmation.fee,slippageBps:confirmation.slippage},'Costes de simulación actualizados.');else ok=await mutate('archive',{requestId,archived:confirmation.archived},confirmation.archived?'Cartera archivada. El historial se conserva.':'Cartera restaurada.');if(ok)setConfirmation(null);}
 async function saveName(event:FormEvent){event.preventDefault();const value=renameValue.trim();if(!value||value.length>60){setError('Indica un nombre de hasta 60 caracteres.');return;}renameId.current??=crypto.randomUUID();if(await mutate('rename',{requestId:renameId.current,name:value},'Nombre de la cartera actualizado.')){setRenaming(false);renameId.current=null;}}
 async function saveNote(event:FormEvent){event.preventDefault();if(!note.trim())return;noteId.current??=crypto.randomUUID();if(await mutate('journal',{requestId:noteId.current,note:note.trim()},'Nota registrada.')){setNote('');noteId.current=null;}}
